<template>
  <div class="project-tree-item">
    <!-- Project row -->
    <div class="project-row" @click="$emit('select', project)">
      <!-- Expand toggle -->
      <q-btn
        v-if="hasMissions"
        flat
        dense
        round
        size="xs"
        :icon="expanded ? 'expand_more' : 'chevron_right'"
        class="expand-btn"
        @click.stop="expanded = !expanded"
      />
      <div v-else class="expand-placeholder" />

      <!-- Folder icon -->
      <q-icon
        name="folder"
        size="18px"
        color="primary"
        class="q-mr-xs status-icon"
      />

      <!-- Project name + description -->
      <div class="project-info">
        <span class="project-name">{{ project.name }}</span>
        <span v-if="project.description" class="project-desc">{{ project.description }}</span>
      </div>

      <q-space />

      <!-- Due date -->
      <span v-if="project.due_date" class="project-meta">
        <q-icon name="event" size="14px" />
        {{ formattedDueDate }}
      </span>

      <!-- Member count -->
      <span v-if="(project.member_ids || []).length > 0" class="project-meta">
        <q-icon name="group" size="14px" />
        {{ project.member_ids.length }}
      </span>

      <!-- Mission count -->
      <span v-if="hasMissions" class="project-meta">
        <q-icon name="rocket_launch" size="14px" />
        {{ allMissions.length }}
      </span>

      <!-- Status badge -->
      <StatusBadge :status="project.status" size="sm" />

      <!-- Three-dot menu -->
      <q-btn
        flat
        round
        dense
        icon="more_vert"
        size="sm"
        class="actions-btn"
        @click.stop
      >
        <q-menu>
          <q-list dense>
            <q-item clickable v-close-popup @click.stop="$emit('edit', project)">
              <q-item-section avatar><q-icon name="edit" size="xs" /></q-item-section>
              <q-item-section>Edit</q-item-section>
            </q-item>
            <q-separator />
            <q-item clickable v-close-popup @click.stop="$emit('delete', project)" class="text-negative">
              <q-item-section avatar><q-icon name="delete" size="xs" /></q-item-section>
              <q-item-section>Delete</q-item-section>
            </q-item>
          </q-list>
        </q-menu>
      </q-btn>
    </div>

    <!-- Missions (expanded) -->
    <div v-if="expanded && hasMissions" class="project-missions">
      <div
        v-for="mission in allMissions"
        :key="mission.id"
        class="mission-row"
        @click.stop="$emit('select-mission', mission)"
      >
        <span class="mission-title">{{ mission.name }}</span>
        <q-space />
        <StatusBadge :status="mission.status" size="sm" />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetProject, DocNetProjectMissionRef } from 'src/@types/docnet';
import StatusBadge from '../../shared/StatusBadge.vue';

export default defineComponent({
  name: 'ProjectTreeItem',

  components: { StatusBadge },

  props: {
    project: {
      type: Object as PropType<DocNetProject>,
      required: true,
    },
  },

  emits: ['select', 'select-mission', 'edit', 'delete'],

  data() {
    return {
      expanded: false,
    };
  },

  computed: {
    allMissions(): DocNetProjectMissionRef[] {
      const direct = this.project.missions || [];
      const extra = this.project.all_missions || [];
      const seen = new Set(direct.map((m) => m.id));
      return [...direct, ...extra.filter((m) => !seen.has(m.id))];
    },

    hasMissions(): boolean {
      return this.allMissions.length > 0;
    },

    formattedDueDate(): string {
      if (!this.project.due_date) return '';
      const date = new Date(this.project.due_date);
      return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    },
  },
});
</script>

